export async function fetchSampleFile(kind) {
  const res = await fetch(`/samples/${kind}.png`)
  if (!res.ok) throw new Error(`Sample ${kind} unavailable`)
  const blob = await res.blob()
  const fixture = SAMPLE_FIXTURES[kind]
  return new File([blob], `${kind}_${fixture.fdNumber}.png`, { type: 'image/png' })
}

export async function fetchSampleHash(kind) {
  try {
    const res = await fetch(`/samples/${kind}.png`)
    if (!res.ok) return null
    const buffer = await res.arrayBuffer()
    const digest = await crypto.subtle.digest('SHA-256', buffer)
    return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('')
  } catch {
    return null
  }
}
